export const el=(tag,className='',text='')=>{const e=document.createElement(tag);e.className=className;e.textContent=text;return e};
export const fmt=(v,d=3)=>Number(v).toFixed(d).replace(/\.?0+$/,'')||'0';
export function makeLab(container,{title='',subtitle='',lang='ru',tag='LIVE'}={}){const root=el('section','lab-shell');root.lang=lang;const head=el('header','lab-head'),badge=el('span','lab-tag',tag),h=el('h3','',title),sub=el('p','',subtitle);head.append(badge,h,sub);const body=el('div','lab-body'),view=el('div','lab-view'),controls=el('div','lab-controls'),readout=el('div','lab-readout'),footer=el('div','lab-footer');body.append(view,controls);root.append(head,body,readout,footer);container.append(root);return {root,view,controls,readout,footer}}
export function addSlider(parent,{label,min,max,step=.1,value,onChange=()=>{},format=v=>fmt(v)}={}){const row=el('label','control'),top=el('span','control-top'),name=el('span','',label),output=el('output','control-value',format(value)),input=el('input');input.type='range';Object.assign(input,{min,max,step,value});input.setAttribute('aria-label',label);top.append(name,output);row.append(top,input);parent.append(row);input.addEventListener('input',()=>{output.textContent=format(+input.value);onChange(+input.value)});input.setValue=v=>{input.value=v;output.textContent=format(+input.value)};return input}
export function addSelect(parent,{label,options,value,onChange=()=>{}}){const row=el('label','control'),name=el('span','control-top',label),input=el('select','lab-select');input.setAttribute('aria-label',label);for(const o of options){const opt=el('option','',o.label);opt.value=o.value;input.append(opt)}input.value=value;input.addEventListener('change',()=>onChange(input.value));row.append(name,input);parent.append(row);return input}
export function addButton(parent,label,onClick,variant=''){const b=el('button','lab-button '+variant,label);b.type='button';b.addEventListener('click',onClick);parent.append(b);return b}
export function addToggle(parent,label,checked,onChange=()=>{}){const row=el('label','lab-toggle'),input=el('input');input.type='checkbox';input.checked=checked;input.addEventListener('change',()=>onChange(input.checked));row.append(input,document.createTextNode(label));parent.append(row);return input}
export function createCanvas(parent,width=900,height=450){const canvas=el('canvas','lab-canvas');canvas.width=width;canvas.height=height;parent.append(canvas);return canvas}
